insert into exams (id, slug, name, short_name, authority, scope, state, about, frequency, color, emoji, next_exam_date, eligibility, highlights, official_site, vacancies) values
  ('ctet', 'ctet', '{"en":"CTET — Central Teacher Eligibility Test","hi":"CTET — केंद्रीय शिक्षक पात्रता परीक्षा"}'::jsonb, 'CTET', '{"en":"Central Board of Secondary Education (CBSE)","hi":"केंद्रीय माध्यमिक शिक्षा बोर्ड (CBSE)"}'::jsonb, 'national', null, '{"en":"The national eligibility test for teaching posts in KVS, NVS, central schools and most state boards. The certificate is now valid for life.","hi":"KVS, NVS, केंद्रीय विद्यालयों तथा अधिकांश राज्य बोर्डों में शिक्षक पदों हेतु राष्ट्रीय पात्रता परीक्षा। प्रमाणपत्र अब आजीवन मान्य है।"}'::jsonb, '{"en":"Notified by CBSE; the 2026 cycle was held in September","hi":"CBSE द्वारा अधिसूचित; 2026 चक्र सितंबर में आयोजित"}'::jsonb, '#4F46E5', '🇮🇳', '2026-09-06'::date, '[{"en":"Paper 1: Senior Secondary (50%) + 2-year D.El.Ed / 4-year B.El.Ed","hi":"पेपर 1: 12वीं (50%) + 2 वर्षीय D.El.Ed / 4 वर्षीय B.El.Ed"},{"en":"Paper 2: Graduation (50%) + B.Ed / D.El.Ed as applicable","hi":"पेपर 2: स्नातक (50%) + B.Ed / D.El.Ed यथालागू"},{"en":"No upper age limit for appearing","hi":"परीक्षा में बैठने हेतु कोई अधिकतम आयु सीमा नहीं"}]'::jsonb, '[{"en":"Certificate valid for lifetime","hi":"प्रमाणपत्र आजीवन मान्य"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"},{"en":"Accepted by 20+ states","hi":"20+ राज्यों में मान्य"}]'::jsonb, 'https://ctet.nic.in', null),
  ('htet', 'htet', '{"en":"HTET — Haryana Teacher Eligibility Test","hi":"HTET — हरियाणा शिक्षक पात्रता परीक्षा"}'::jsonb, 'HTET', '{"en":"Board of School Education Haryana (BSEH), Bhiwani","hi":"हरियाणा विद्यालय शिक्षा बोर्ड (BSEH), भिवानी"}'::jsonb, 'state', '{"en":"Haryana","hi":"हरियाणा"}'::jsonb, '{"en":"Eligibility test for PRT, TGT and PGT posts in Haryana government schools. Uniquely includes a 30-mark General Studies section with Haryana GK.","hi":"हरियाणा राजकीय विद्यालयों में PRT, TGT एवं PGT पदों हेतु पात्रता परीक्षा। इसमें हरियाणा GK सहित 30 अंकों का सामान्य अध्ययन खंड विशेष रूप से होता है।"}'::jsonb, '{"en":"Annual — the 2026 cycle was held on 4-5 July","hi":"वार्षिक — 2026 चक्र 4-5 जुलाई को आयोजित"}'::jsonb, '#059669', '🌾', null, '[{"en":"Level 1 (PRT): 12th with 50% + D.El.Ed","hi":"स्तर 1 (PRT): 12वीं 50% अंकों के साथ + D.El.Ed"},{"en":"Level 2 (TGT): Graduation + B.Ed","hi":"स्तर 2 (TGT): स्नातक + B.Ed"},{"en":"Level 3 (PGT): Post Graduation with 50% + B.Ed","hi":"स्तर 3 (PGT): 50% अंकों सहित स्नातकोत्तर + B.Ed"}]'::jsonb, '[{"en":"Certificate valid for lifetime","hi":"प्रमाणपत्र आजीवन मान्य"},{"en":"Haryana GK carries real weight","hi":"हरियाणा GK का वास्तविक महत्व"},{"en":"Gateway to HSSC TGT/PGT recruitment","hi":"HSSC TGT/PGT भर्ती का प्रवेश द्वार"}]'::jsonb, 'https://bseh.org.in', null),
  ('uptet', 'uptet', '{"en":"UPTET — Uttar Pradesh Teacher Eligibility Test","hi":"UPTET — उत्तर प्रदेश शिक्षक पात्रता परीक्षा"}'::jsonb, 'UPTET', '{"en":"UP Education Service Selection Commission (UPESSC)","hi":"उत्तर प्रदेश शिक्षा सेवा चयन आयोग (UPESSC)"}'::jsonb, 'state', '{"en":"Uttar Pradesh","hi":"उत्तर प्रदेश"}'::jsonb, '{"en":"India''s largest state TET by applicants. Clearing it is mandatory for the 69000/Super TET primary teacher recruitments in UP.","hi":"आवेदकों की संख्या के आधार पर भारत की सबसे बड़ी राज्य TET। UP की 69000/सुपर TET प्राथमिक शिक्षक भर्ती हेतु इसे उत्तीर्ण करना अनिवार्य है।"}'::jsonb, '{"en":"Announced by ERA, UP — typically annual","hi":"ERA, UP द्वारा घोषित — प्रायः वार्षिक"}'::jsonb, '#DC2626', '🕌', null, '[{"en":"Primary Level: 12th with 50% + D.El.Ed / BTC","hi":"प्राथमिक स्तर: 12वीं 50% + D.El.Ed / BTC"},{"en":"Upper Primary: Graduation + B.Ed / BTC","hi":"उच्च प्राथमिक: स्नातक + B.Ed / BTC"},{"en":"UP domicile preferred for recruitment, not for the test","hi":"भर्ती हेतु UP मूल निवास वांछित, परीक्षा हेतु नहीं"}]'::jsonb, '[{"en":"Mandatory for Super TET","hi":"सुपर TET हेतु अनिवार्य"},{"en":"Language II: English, Urdu or Sanskrit","hi":"भाषा II: अंग्रेज़ी, उर्दू या संस्कृत"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://upessc.up.gov.in', null),
  ('bihartet', 'bihar-tet', '{"en":"Bihar TET / BPSC TRE","hi":"बिहार TET / BPSC TRE"}'::jsonb, 'BiharTET', '{"en":"Bihar School Examination Board & BPSC","hi":"बिहार विद्यालय परीक्षा समिति एवं BPSC"}'::jsonb, 'state', '{"en":"Bihar","hi":"बिहार"}'::jsonb, '{"en":"BSEB conducts the eligibility test; BPSC conducts the Teacher Recruitment Exam (TRE) that fills lakhs of posts across Classes 1-12.","hi":"BSEB पात्रता परीक्षा आयोजित करता है; BPSC शिक्षक भर्ती परीक्षा (TRE) आयोजित करता है जो कक्षा 1-12 के लाखों पदों को भरती है।"}'::jsonb, '{"en":"TRE cycles announced by BPSC through the year","hi":"BPSC द्वारा वर्ष भर TRE चक्र घोषित"}'::jsonb, '#EA580C', '🪷', '2026-09-22'::date, '[{"en":"Paper 1: 12th with 50% + D.El.Ed","hi":"पेपर 1: 12वीं 50% + D.El.Ed"},{"en":"Paper 2: Graduation + B.Ed","hi":"पेपर 2: स्नातक + B.Ed"},{"en":"TRE additionally tests language and subject papers","hi":"TRE में अतिरिक्त रूप से भाषा एवं विषय पेपर होते हैं"}]'::jsonb, '[{"en":"Largest recruitment drive in India","hi":"भारत का सबसे बड़ा भर्ती अभियान"},{"en":"Negative marking in TRE","hi":"TRE में नकारात्मक अंकन"},{"en":"Bihar-specific GK section","hi":"बिहार विशिष्ट GK खंड"}]'::jsonb, 'https://bpsc.bihar.gov.in', 32388),
  ('dsssb', 'dsssb', '{"en":"DSSSB PRT / TGT / PGT","hi":"DSSSB PRT / TGT / PGT"}'::jsonb, 'DSSSB', '{"en":"Delhi Subordinate Services Selection Board","hi":"दिल्ली अधीनस्थ सेवा चयन बोर्ड"}'::jsonb, 'state', '{"en":"Delhi NCT","hi":"दिल्ली"}'::jsonb, '{"en":"Direct recruitment to Delhi government and MCD schools. Section A tests general ability; Section B is entirely subject and teaching methodology.","hi":"दिल्ली सरकार एवं MCD विद्यालयों में सीधी भर्ती। खंड A सामान्य योग्यता तथा खंड B पूर्णतः विषय एवं शिक्षण विधि पर आधारित।"}'::jsonb, '{"en":"Post-wise notifications through the year","hi":"वर्ष भर पदवार अधिसूचनाएँ"}'::jsonb, '#0F766E', '🏛️', '2026-09-21'::date, '[{"en":"PRT: 12th with 50% + D.El.Ed + CTET Paper 1","hi":"PRT: 12वीं 50% + D.El.Ed + CTET पेपर 1"},{"en":"TGT: Graduation with 50% + B.Ed + CTET Paper 2","hi":"TGT: स्नातक 50% + B.Ed + CTET पेपर 2"},{"en":"PGT: Post Graduation with 50% + B.Ed","hi":"PGT: स्नातकोत्तर 50% + B.Ed"}]'::jsonb, '[{"en":"Negative marking of 0.25 per wrong answer","hi":"प्रत्येक गलत उत्तर पर 0.25 ऋणात्मक अंकन"},{"en":"Central pay scale posts","hi":"केंद्रीय वेतनमान पद"},{"en":"200 marks in 2 hours","hi":"2 घंटे में 200 अंक"}]'::jsonb, 'https://dsssbonline.nic.in', 1348),
  ('kvs', 'kvs', '{"en":"KVS PRT / TGT / PGT","hi":"KVS PRT / TGT / PGT"}'::jsonb, 'KVS', '{"en":"Kendriya Vidyalaya Sangathan","hi":"केंद्रीय विद्यालय संगठन"}'::jsonb, 'national', null, '{"en":"Recruitment to 1250+ Kendriya Vidyalayas nationwide. The paper is 80 marks of subject knowledge sitting on top of a 70-mark general and pedagogy base.","hi":"देशभर के 1250+ केंद्रीय विद्यालयों में भर्ती। पेपर में 70 अंकों के सामान्य एवं शिक्षाशास्त्र आधार पर 80 अंकों का विषय ज्ञान होता है।"}'::jsonb, '{"en":"As per KVS vacancy notification","hi":"KVS रिक्ति अधिसूचना के अनुसार"}'::jsonb, '#1D4ED8', '🏫', null, '[{"en":"PRT: 12th with 50% + D.El.Ed + CTET Paper 1","hi":"PRT: 12वीं 50% + D.El.Ed + CTET पेपर 1"},{"en":"TGT: Graduation with 50% in subject + B.Ed + CTET Paper 2","hi":"TGT: विषय में 50% सहित स्नातक + B.Ed + CTET पेपर 2"},{"en":"PGT: Post Graduation with 50% + B.Ed","hi":"PGT: स्नातकोत्तर 50% + B.Ed"}]'::jsonb, '[{"en":"All-India transferable central job","hi":"अखिल भारतीय स्थानांतरणीय केंद्रीय नौकरी"},{"en":"Interview + performance test for some posts","hi":"कुछ पदों हेतु साक्षात्कार + प्रदर्शन परीक्षा"},{"en":"Computer literacy section is scoring","hi":"कंप्यूटर साक्षरता खंड स्कोरिंग है"}]'::jsonb, 'https://kvsangathan.nic.in', 9921),
  ('nvs', 'nvs', '{"en":"NVS PRT / TGT / PGT","hi":"NVS PRT / TGT / PGT"}'::jsonb, 'NVS', '{"en":"Navodaya Vidyalaya Samiti","hi":"नवोदय विद्यालय समिति"}'::jsonb, 'national', null, '{"en":"Recruitment to 650+ residential Jawahar Navodaya Vidyalayas. Teaching aptitude and domain knowledge carry the paper.","hi":"650+ आवासीय जवाहर नवोदय विद्यालयों में भर्ती। शिक्षण अभिरुचि एवं विषय ज्ञान पेपर का मुख्य आधार हैं।"}'::jsonb, '{"en":"As per NVS vacancy notification","hi":"NVS रिक्ति अधिसूचना के अनुसार"}'::jsonb, '#7C2D12', '🌳', null, '[{"en":"PRT: 12th with 50% + D.El.Ed + CTET Paper 1","hi":"PRT: 12वीं 50% + D.El.Ed + CTET पेपर 1"},{"en":"TGT: Graduation with 50% + B.Ed + CTET Paper 2","hi":"TGT: स्नातक 50% + B.Ed + CTET पेपर 2"},{"en":"PGT: Post Graduation with 50% + B.Ed","hi":"PGT: स्नातकोत्तर 50% + B.Ed"}]'::jsonb, '[{"en":"Residential posting with quarters","hi":"आवास सहित आवासीय पदस्थापन"},{"en":"Teaching aptitude is a full section","hi":"शिक्षण अभिरुचि एक पूर्ण खंड है"},{"en":"Regional language competency tested","hi":"क्षेत्रीय भाषा दक्षता की परीक्षा"}]'::jsonb, 'https://navodaya.gov.in', 5841),
  ('reet', 'reet', '{"en":"REET — Rajasthan Eligibility Exam for Teachers","hi":"REET — राजस्थान अध्यापक पात्रता परीक्षा"}'::jsonb, 'REET', '{"en":"Board of Secondary Education, Rajasthan (Ajmer)","hi":"माध्यमिक शिक्षा बोर्ड, राजस्थान (अजमेर)"}'::jsonb, 'state', '{"en":"Rajasthan","hi":"राजस्थान"}'::jsonb, '{"en":"Eligibility test for Rajasthan third-grade teacher posts. Clearing REET makes you eligible for the REET Mains recruitment exam.","hi":"राजस्थान तृतीय श्रेणी अध्यापक पदों हेतु पात्रता परीक्षा। REET उत्तीर्ण करने पर आप REET मुख्य भर्ती परीक्षा हेतु पात्र होते हैं।"}'::jsonb, '{"en":"As notified by BSER — recent cycles annual","hi":"BSER द्वारा अधिसूचित — हाल के चक्र वार्षिक"}'::jsonb, '#9333EA', '🐪', null, '[{"en":"Level 1: 12th with 50% + D.El.Ed","hi":"स्तर 1: 12वीं 50% + D.El.Ed"},{"en":"Level 2: Graduation + B.Ed","hi":"स्तर 2: स्नातक + B.Ed"},{"en":"Rajasthan GK is compulsory in REET Mains","hi":"REET मुख्य परीक्षा में राजस्थान GK अनिवार्य"}]'::jsonb, '[{"en":"Certificate valid for lifetime","hi":"प्रमाणपत्र आजीवन मान्य"},{"en":"2.5 hours for 150 questions","hi":"150 प्रश्नों हेतु 2.5 घंटे"},{"en":"Level 2 has Maths-Science and SST streams","hi":"स्तर 2 में गणित-विज्ञान एवं SST वर्ग"}]'::jsonb, 'https://rajeduboard.rajasthan.gov.in', 10208),
  ('hssc-tgt-pgt', 'hssc-tgt-pgt', '{"en":"HSSC TGT / PGT / PRT — Haryana","hi":"HSSC TGT / PGT / PRT — हरियाणा"}'::jsonb, 'HSSC', '{"en":"Haryana Staff Selection Commission","hi":"हरियाणा कर्मचारी चयन आयोग"}'::jsonb, 'state', '{"en":"Haryana","hi":"हरियाणा"}'::jsonb, '{"en":"The recruitment exam that follows HTET. Three-quarters of the paper is subject and aptitude; one quarter is Haryana-specific GK.","hi":"HTET के बाद होने वाली भर्ती परीक्षा। पेपर का तीन-चौथाई भाग विषय एवं अभिरुचि तथा एक-चौथाई हरियाणा विशिष्ट GK होता है।"}'::jsonb, '{"en":"Advertisement-wise, after CET screening","hi":"CET स्क्रीनिंग के बाद विज्ञापनवार"}'::jsonb, '#065F46', '🎓', '2026-09-21'::date, '[{"en":"Valid HTET certificate for the relevant level","hi":"संबंधित स्तर हेतु वैध HTET प्रमाणपत्र"},{"en":"Haryana CET qualification where applicable","hi":"यथालागू हरियाणा CET अर्हता"},{"en":"Post-specific degree with B.Ed","hi":"पदानुसार डिग्री सहित B.Ed"}]'::jsonb, '[{"en":"25% weight to Haryana GK","hi":"हरियाणा GK को 25% भार"},{"en":"100 questions in 90 minutes","hi":"90 मिनट में 100 प्रश्न"},{"en":"Socio-economic criteria removed","hi":"सामाजिक-आर्थिक मानदंड हटाए गए"}]'::jsonb, 'https://hssc.gov.in', 8394),
  ('supertet', 'super-tet', '{"en":"UP Super TET","hi":"UP सुपर TET"}'::jsonb, 'SuperTET', '{"en":"Basic Education Board, Uttar Pradesh","hi":"बेसिक शिक्षा परिषद, उत्तर प्रदेश"}'::jsonb, 'state', '{"en":"Uttar Pradesh","hi":"उत्तर प्रदेश"}'::jsonb, '{"en":"The recruitment exam for UP primary assistant teachers, open only to UPTET/CTET qualified candidates.","hi":"UP प्राथमिक सहायक अध्यापक भर्ती परीक्षा, जो केवल UPTET/CTET उत्तीर्ण अभ्यर्थियों हेतु खुली है।"}'::jsonb, '{"en":"As per UPBEB recruitment cycle","hi":"UPBEB भर्ती चक्र के अनुसार"}'::jsonb, '#BE123C', '⭐', null, '[{"en":"UPTET or CTET qualified","hi":"UPTET अथवा CTET उत्तीर्ण"},{"en":"Graduation + D.El.Ed / B.Ed","hi":"स्नातक + D.El.Ed / B.Ed"}]'::jsonb, '[{"en":"150 marks written + 10 marks academic weightage","hi":"150 अंक लिखित + 10 अंक शैक्षणिक भारांक"},{"en":"Includes teaching aptitude and information tech","hi":"शिक्षण अभिरुचि एवं सूचना तकनीक सम्मिलित"}]'::jsonb, 'https://upbasiceduboard.gov.in', null),
  ('mptet', 'mp-tet', '{"en":"MPTET Varg 1 / 2 / 3","hi":"MPTET वर्ग 1 / 2 / 3"}'::jsonb, 'MPTET', '{"en":"MP Employee Selection Board (ESB)","hi":"मध्यप्रदेश कर्मचारी चयन मंडल (ESB)"}'::jsonb, 'state', '{"en":"Madhya Pradesh","hi":"मध्य प्रदेश"}'::jsonb, '{"en":"Madhya Pradesh eligibility test across Varg 3 (primary), Varg 2 (middle) and Varg 1 (higher secondary) teacher posts.","hi":"वर्ग 3 (प्राथमिक), वर्ग 2 (माध्यमिक) एवं वर्ग 1 (उच्चतर माध्यमिक) शिक्षक पदों हेतु मध्य प्रदेश पात्रता परीक्षा।"}'::jsonb, '{"en":"As notified by MPESB","hi":"MPESB द्वारा अधिसूचित"}'::jsonb, '#0369A1', '🐅', null, '[{"en":"Varg 3: 12th with 50% + D.El.Ed","hi":"वर्ग 3: 12वीं 50% + D.El.Ed"},{"en":"Varg 2: Graduation + B.Ed","hi":"वर्ग 2: स्नातक + B.Ed"}]'::jsonb, '[{"en":"MP GK section in the recruitment stage","hi":"भर्ती चरण में MP GK खंड"},{"en":"Certificate validity for lifetime","hi":"प्रमाणपत्र आजीवन मान्य"}]'::jsonb, 'https://esb.mp.gov.in', null),
  ('bihar-stet', 'bihar-stet', '{"en":"Bihar STET","hi":"बिहार STET"}'::jsonb, 'STET', '{"en":"Bihar School Examination Board","hi":"बिहार विद्यालय परीक्षा समिति"}'::jsonb, 'state', '{"en":"Bihar","hi":"बिहार"}'::jsonb, '{"en":"Secondary Teacher Eligibility Test for Classes 9-10 (Paper 1) and 11-12 (Paper 2) in Bihar.","hi":"बिहार में कक्षा 9-10 (पेपर 1) एवं 11-12 (पेपर 2) हेतु माध्यमिक शिक्षक पात्रता परीक्षा।"}'::jsonb, '{"en":"As notified by BSEB","hi":"BSEB द्वारा अधिसूचित"}'::jsonb, '#7E22CE', '📜', null, '[{"en":"Paper 1: Graduation with 50% + B.Ed","hi":"पेपर 1: स्नातक 50% + B.Ed"},{"en":"Paper 2: Post Graduation with 50% + B.Ed","hi":"पेपर 2: स्नातकोत्तर 50% + B.Ed"}]'::jsonb, '[{"en":"100 subject + 50 teaching aptitude marks","hi":"100 विषय + 50 शिक्षण अभिरुचि अंक"},{"en":"Gateway to BPSC TRE secondary posts","hi":"BPSC TRE माध्यमिक पदों का प्रवेश द्वार"}]'::jsonb, 'https://secondary.biharboardonline.com', null),
  ('wbtet', 'wb-tet', '{"en":"WB TET (Primary & Upper Primary)","hi":"WB TET (प्राथमिक एवं उच्च प्राथमिक)"}'::jsonb, 'WBTET', '{"en":"West Bengal Board of Primary Education","hi":"पश्चिम बंगाल प्राथमिक शिक्षा बोर्ड"}'::jsonb, 'state', '{"en":"West Bengal","hi":"पश्चिम बंगाल"}'::jsonb, '{"en":"Eligibility test for primary and upper-primary teacher posts in West Bengal government schools.","hi":"पश्चिम बंगाल के सरकारी विद्यालयों में प्राथमिक एवं उच्च प्राथमिक शिक्षक पदों हेतु पात्रता परीक्षा।"}'::jsonb, '{"en":"As notified by WBBPE","hi":"WBBPE द्वारा अधिसूचित"}'::jsonb, '#B91C1C', '🐟', null, '[{"en":"12th with 50% + D.El.Ed for primary","hi":"प्राथमिक हेतु 12वीं 50% + D.El.Ed"},{"en":"Graduation + B.Ed for upper primary","hi":"उच्च प्राथमिक हेतु स्नातक + B.Ed"}]'::jsonb, '[{"en":"150 questions, 2.5 hours","hi":"150 प्रश्न, 2.5 घंटे"},{"en":"Bengali/Hindi as Language I","hi":"भाषा I के रूप में बांग्ला/हिंदी"}]'::jsonb, 'https://wbbpe.org', null),
  ('awes', 'army-public-school', '{"en":"AWES Army Public School (PRT/TGT/PGT)","hi":"AWES आर्मी पब्लिक स्कूल (PRT/TGT/PGT)"}'::jsonb, 'APS', '{"en":"Army Welfare Education Society","hi":"आर्मी वेलफेयर एजुकेशन सोसाइटी"}'::jsonb, 'national', null, '{"en":"Online screening test for 130+ Army Public Schools. Part A is teaching aptitude and reasoning; Part B is the subject.","hi":"130+ आर्मी पब्लिक स्कूलों हेतु ऑनलाइन स्क्रीनिंग परीक्षा। भाग A शिक्षण अभिरुचि एवं तर्कशक्ति तथा भाग B विषय आधारित।"}'::jsonb, '{"en":"Annual — usually November","hi":"वार्षिक — प्रायः नवंबर"}'::jsonb, '#166534', '🎖️', null, '[{"en":"B.Ed mandatory for all posts","hi":"सभी पदों हेतु B.Ed अनिवार्य"},{"en":"Age below 40 for fresh candidates","hi":"नए अभ्यर्थियों हेतु आयु 40 वर्ष से कम"}]'::jsonb, '[{"en":"Score card valid for lifetime","hi":"स्कोर कार्ड आजीवन मान्य"},{"en":"Negative marking of 0.25","hi":"0.25 ऋणात्मक अंकन"}]'::jsonb, 'https://awesindia.com', null),
  ('emrs', 'emrs', '{"en":"EMRS Teaching Staff (NESTS)","hi":"EMRS शिक्षण स्टाफ (NESTS)"}'::jsonb, 'EMRS', '{"en":"National Education Society for Tribal Students","hi":"राष्ट्रीय जनजातीय छात्र शिक्षा समिति"}'::jsonb, 'national', null, '{"en":"Recruitment to Eklavya Model Residential Schools for tribal students across India.","hi":"देशभर में जनजातीय छात्रों हेतु एकलव्य आदर्श आवासीय विद्यालयों में भर्ती।"}'::jsonb, '{"en":"As per NESTS notification","hi":"NESTS अधिसूचना के अनुसार"}'::jsonb, '#7C3AED', '🏞️', null, '[{"en":"TGT: Graduation + B.Ed + CTET Paper 2","hi":"TGT: स्नातक + B.Ed + CTET पेपर 2"},{"en":"PGT: Post Graduation + B.Ed","hi":"PGT: स्नातकोत्तर + B.Ed"}]'::jsonb, '[{"en":"Residential campus posting","hi":"आवासीय परिसर पदस्थापन"},{"en":"Central government pay scale","hi":"केंद्र सरकार वेतनमान"}]'::jsonb, 'https://emrs.tribal.gov.in', null),
  ('hptet', 'hptet', '{"en":"HP TET — Himachal Pradesh Teacher Eligibility Test","hi":"HP TET — हिमाचल प्रदेश शिक्षक पात्रता परीक्षा"}'::jsonb, 'HP TET', '{"en":"Himachal Pradesh Board of School Education (HPBOSE), Dharamshala","hi":"हिमाचल प्रदेश स्कूल शिक्षा बोर्ड (HPBOSE), धर्मशाला"}'::jsonb, 'state', '{"en":"Himachal Pradesh","hi":"हिमाचल प्रदेश"}'::jsonb, '{"en":"Required for teaching posts in Himachal Pradesh government and aided schools. Conducted by HPBOSE, usually alongside the TET for non-medical and medical subjects.","hi":"हिमाचल प्रदेश के सरकारी एवं सहायता प्राप्त विद्यालयों में शिक्षक पदों हेतु आवश्यक। HPBOSE द्वारा आयोजित।"}'::jsonb, '{"en":"Usually twice a year","hi":"प्रायः वर्ष में दो बार"}'::jsonb, '#0369A1', '🏔️', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Hindi, Language II is English","hi":"भाषा I हिंदी, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://hpbose.org', null),
  ('pstet', 'pstet', '{"en":"PSTET — Punjab State Teacher Eligibility Test","hi":"PSTET — पंजाब राज्य शिक्षक पात्रता परीक्षा"}'::jsonb, 'PSTET', '{"en":"Punjab School Education Board (PSEB), Mohali","hi":"पंजाब स्कूल शिक्षा बोर्ड (PSEB), मोहाली"}'::jsonb, 'state', '{"en":"Punjab","hi":"पंजाब"}'::jsonb, '{"en":"Mandatory for teaching posts in Punjab government schools. Language I is Punjabi, which is also the medium for a large share of the paper.","hi":"पंजाब के सरकारी विद्यालयों में शिक्षक पदों हेतु अनिवार्य। भाषा I पंजाबी है।"}'::jsonb, '{"en":"Announced by PSEB — typically annual","hi":"PSEB द्वारा घोषित — प्रायः वार्षिक"}'::jsonb, '#CA8A04', '🌾', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Punjabi, Language II is English","hi":"भाषा I पंजाबी, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://pseb.ac.in', null),
  ('utet', 'utet', '{"en":"UTET — Uttarakhand Teacher Eligibility Test","hi":"UTET — उत्तराखंड शिक्षक पात्रता परीक्षा"}'::jsonb, 'UTET', '{"en":"Uttarakhand Board of School Education (UBSE), Ramnagar","hi":"उत्तराखंड विद्यालयी शिक्षा परिषद (UBSE), रामनगर"}'::jsonb, 'state', '{"en":"Uttarakhand","hi":"उत्तराखंड"}'::jsonb, '{"en":"Required for primary and upper-primary teaching posts in Uttarakhand. Certificate validity follows the NCTE norm.","hi":"उत्तराखंड में प्राथमिक एवं उच्च प्राथमिक शिक्षक पदों हेतु आवश्यक।"}'::jsonb, '{"en":"Announced by UBSE — typically annual","hi":"UBSE द्वारा घोषित — प्रायः वार्षिक"}'::jsonb, '#15803D', '⛰️', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Hindi, Language II is English","hi":"भाषा I हिंदी, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://ukutet.com', null),
  ('jtet', 'jtet', '{"en":"JTET — Jharkhand Teacher Eligibility Test","hi":"JTET — झारखंड शिक्षक पात्रता परीक्षा"}'::jsonb, 'JTET', '{"en":"Jharkhand Academic Council (JAC), Ranchi","hi":"झारखंड अधिविद्य परिषद (JAC), राँची"}'::jsonb, 'state', '{"en":"Jharkhand","hi":"झारखंड"}'::jsonb, '{"en":"Required for teaching posts in Jharkhand government schools. The state offers several regional and tribal languages as Language II.","hi":"झारखंड के सरकारी विद्यालयों में शिक्षक पदों हेतु आवश्यक। भाषा II में कई क्षेत्रीय एवं जनजातीय भाषाएँ उपलब्ध हैं।"}'::jsonb, '{"en":"Announced by JAC — irregular","hi":"JAC द्वारा घोषित — अनियमित"}'::jsonb, '#7C2D12', '🌳', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Hindi, Language II is English","hi":"भाषा I हिंदी, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://jac.jharkhand.gov.in', null),
  ('otet', 'otet', '{"en":"OTET — Odisha Teacher Eligibility Test","hi":"OTET — ओडिशा शिक्षक पात्रता परीक्षा"}'::jsonb, 'OTET', '{"en":"Board of Secondary Education, Odisha (BSE Odisha), Cuttack","hi":"माध्यमिक शिक्षा बोर्ड, ओडिशा (BSE Odisha), कटक"}'::jsonb, 'state', '{"en":"Odisha","hi":"ओडिशा"}'::jsonb, '{"en":"Required for teaching posts in Odisha government and aided schools. Language I is Odia.","hi":"ओडिशा के सरकारी एवं सहायता प्राप्त विद्यालयों में शिक्षक पदों हेतु आवश्यक। भाषा I ओड़िया है।"}'::jsonb, '{"en":"Announced by BSE Odisha — typically annual","hi":"BSE ओडिशा द्वारा घोषित — प्रायः वार्षिक"}'::jsonb, '#0891B2', '🛕', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Odia, Language II is English","hi":"भाषा I ओड़िया, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://bseodisha.ac.in', null),
  ('sktet', 'sktet', '{"en":"Sikkim TET — Sikkim Teacher Eligibility Test","hi":"सिक्किम TET — सिक्किम शिक्षक पात्रता परीक्षा"}'::jsonb, 'Sikkim TET', '{"en":"Human Resource Development Department (HRDD), Government of Sikkim","hi":"मानव संसाधन विकास विभाग (HRDD), सिक्किम सरकार"}'::jsonb, 'state', '{"en":"Sikkim","hi":"सिक्किम"}'::jsonb, '{"en":"Required for teaching posts in Sikkim government schools. Language I is Nepali; the state also offers Bhutia, Lepcha and Limboo.","hi":"सिक्किम के सरकारी विद्यालयों में शिक्षक पदों हेतु आवश्यक। भाषा I नेपाली; भूटिया, लेप्चा एवं लिम्बू भी उपलब्ध।"}'::jsonb, '{"en":"Announced by HRDD Sikkim — irregular","hi":"HRDD सिक्किम द्वारा घोषित — अनियमित"}'::jsonb, '#DB2777', '🏞️', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Nepali, Language II is English","hi":"भाषा I नेपाली, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://sikkimhrdd.org', null),
  ('gtet', 'gtet', '{"en":"Gujarat TET — Gujarat Teacher Eligibility Test","hi":"गुजरात TET — गुजरात शिक्षक पात्रता परीक्षा"}'::jsonb, 'Gujarat TET', '{"en":"Gujarat State Examination Board (GSEB), Gandhinagar","hi":"गुजरात राज्य परीक्षा बोर्ड (GSEB), गांधीनगर"}'::jsonb, 'state', '{"en":"Gujarat","hi":"गुजरात"}'::jsonb, '{"en":"Required for teaching posts in Gujarat government and grant-in-aid schools. TET-1 covers classes 1 to 5 and TET-2 covers classes 6 to 8.","hi":"गुजरात के सरकारी एवं अनुदानित विद्यालयों में शिक्षक पदों हेतु आवश्यक। TET-1 कक्षा 1-5, TET-2 कक्षा 6-8।"}'::jsonb, '{"en":"Announced by GSEB — irregular","hi":"GSEB द्वारा घोषित — अनियमित"}'::jsonb, '#EA580C', '🦁', null, '[{"en":"Paper 1 (Classes 1-5): 12th with 50% + D.El.Ed","hi":"पेपर 1 (कक्षा 1-5): 12वीं 50% + D.El.Ed"},{"en":"Paper 2 (Classes 6-8): Graduation with 50% + B.Ed / D.El.Ed","hi":"पेपर 2 (कक्षा 6-8): स्नातक 50% + B.Ed / D.El.Ed"}]'::jsonb, '[{"en":"150 questions, 150 marks, 150 minutes","hi":"150 प्रश्न, 150 अंक, 150 मिनट"},{"en":"Language I is Gujarati, Language II is English","hi":"भाषा I गुजराती, भाषा II अंग्रेज़ी"},{"en":"No negative marking","hi":"कोई नकारात्मक अंकन नहीं"}]'::jsonb, 'https://sebexam.org', null)
