insert into current_affairs (id, title, summary, date, tags, exam_ids) values
  ('ca-nipun-class5', '{"en":"NIPUN Bharat set to be extended up to Class 5","hi":"निपुण भारत मिशन कक्षा 5 तक बढ़ाए जाने की तैयारी"}'::jsonb, '{"en":"The Education Ministry proposes extending the foundational literacy and numeracy mission — currently ending in 2026-27 — up to Class 5, so children who missed the early grades are covered. PARAKH is running the Foundational Learning Study 2026; the PARAKH Rashtriya Sarvekshan 2024 placed literacy and numeracy at about 60%. Expect questions on the mission timeline, PARAKH and the FLN goal.","hi":"शिक्षा मंत्रालय आधारभूत साक्षरता एवं संख्यात्मकता मिशन — जो अभी 2026-27 में समाप्त हो रहा है — को कक्षा 5 तक बढ़ाने का प्रस्ताव कर रहा है, ताकि प्रारंभिक कक्षाएँ छूट जाने वाले बालक भी सम्मिलित हों। PARAKH आधारभूत अधिगम अध्ययन 2026 संचालित कर रहा है; PARAKH राष्ट्रीय सर्वेक्षण 2024 में साक्षरता एवं संख्यात्मकता लगभग 60% रही। मिशन की समय-सीमा, PARAKH तथा FLN लक्ष्य पर प्रश्न अपेक्षित हैं।"}'::jsonb, '2026-08-06'::date, '[{"en":"NIPUN Bharat","hi":"निपुण भारत"},{"en":"FLN","hi":"FLN"}]'::jsonb, array['ctet', 'reet', 'uptet', 'bihartet', 'mptet', 'kvs', 'nvs']::text[]),
  ('ca-pmshri-budget', '{"en":"PM SHRI gets Rs 7,500 crore; Samagra Shiksha Rs 42,100 crore","hi":"PM श्री को ₹7,500 करोड़; समग्र शिक्षा को ₹42,100 करोड़"}'::jsonb, '{"en":"The 2026-27 union budget earmarks Rs 7,500 crore for PM SHRI model schools and Rs 42,100 crore for Samagra Shiksha Abhiyan. PM SHRI is also set to expand into West Bengal, Tamil Nadu and Kerala. Scheme names, their ministries and allocations are standard General Awareness material for DSSSB, KVS and NVS.","hi":"2026-27 के केंद्रीय बजट में PM श्री आदर्श विद्यालयों हेतु ₹7,500 करोड़ तथा समग्र शिक्षा अभियान हेतु ₹42,100 करोड़ आवंटित। PM श्री का विस्तार पश्चिम बंगाल, तमिलनाडु एवं केरल तक होने जा रहा है। योजनाओं के नाम, मंत्रालय एवं आवंटन DSSSB, KVS तथा NVS के सामान्य ज्ञान खंड की सामान्य सामग्री हैं।"}'::jsonb, '2026-08-01'::date, '[{"en":"Schemes","hi":"योजनाएँ"},{"en":"Budget","hi":"बजट"}]'::jsonb, array['dsssb', 'kvs', 'nvs', 'emrs', 'hssc-tgt-pgt', 'awes']::text[]),
  ('ca-ncf-npst', '{"en":"NCF-SE 2023 rollout paired with National Professional Standards for Teachers","hi":"NCF-SE 2023 क्रियान्वयन के साथ शिक्षकों हेतु राष्ट्रीय व्यावसायिक मानक"}'::jsonb, '{"en":"Teacher orientation programmes on NEP 2020 and the National Curriculum Framework for School Education 2023 are running alongside the proposed National Professional Standards for Teachers (NPST) and a National Mentoring Mission. Continuous professional development has shifted from one-off workshops to structured online and hybrid training.","hi":"NEP 2020 तथा राष्ट्रीय पाठ्यचर्या रूपरेखा (विद्यालयी शिक्षा) 2023 पर शिक्षक अभिविन्यास कार्यक्रम, प्रस्तावित राष्ट्रीय व्यावसायिक शिक्षक मानक (NPST) एवं राष्ट्रीय मेंटरिंग मिशन के साथ चल रहे हैं। सतत व्यावसायिक विकास अब एकबारगी कार्यशालाओं के स्थान पर संरचित ऑनलाइन एवं हाइब्रिड प्रशिक्षण बन गया है।"}'::jsonb, '2026-07-28'::date, '[{"en":"NEP 2020","hi":"NEP 2020"},{"en":"NCF-SE","hi":"NCF-SE"}]'::jsonb, array['ctet', 'htet', 'uptet', 'reet', 'kvs', 'nvs', 'dsssb', 'emrs']::text[]),
  ('ca-ctet-sept', '{"en":"CTET September 2026 held on 6 September across 132 cities","hi":"CTET सितंबर 2026 परीक्षा 6 सितंबर को 132 शहरों में"}'::jsonb, '{"en":"CBSE notified the cycle on 11 May 2026 with applications from 11 May to 10 June. Paper II runs 9:30 AM to 12:00 noon and Paper I from 2:30 to 5:00 PM, offline on OMR sheets. Qualifying marks stay at 90/150 for General and 82/150 for OBC, SC and ST.","hi":"CBSE ने 11 मई 2026 को चक्र अधिसूचित किया, आवेदन 11 मई से 10 जून तक। पेपर II प्रातः 9:30 से 12:00 तथा पेपर I अपराह्न 2:30 से 5:00 बजे तक, OMR शीट पर ऑफ़लाइन। अर्हक अंक सामान्य हेतु 90/150 तथा OBC, SC एवं ST हेतु 82/150 यथावत।"}'::jsonb, '2026-05-11'::date, '[{"en":"CTET","hi":"CTET"},{"en":"Exam dates","hi":"परीक्षा तिथि"}]'::jsonb, array['ctet']::text[]),
  ('ca-bpsc-tre4', '{"en":"BPSC TRE 4.0 opens 32,388 teacher posts in Bihar","hi":"BPSC TRE 4.0 में बिहार के 32,388 शिक्षक पद"}'::jsonb, '{"en":"One of the largest teacher recruitment drives in Bihar''s history, covering Classes 1-12. The examination is scheduled for 22-27 September 2026 with results expected in November. Each paper carries 150 questions for 150 marks in 2.5 hours across Language, General Studies and the subject.","hi":"बिहार के इतिहास के सबसे बड़े शिक्षक भर्ती अभियानों में से एक, जो कक्षा 1-12 को कवर करता है। परीक्षा 22-27 सितंबर 2026 को निर्धारित है, परिणाम नवंबर में अपेक्षित। प्रत्येक पेपर में भाषा, सामान्य अध्ययन एवं विषय हेतु 2.5 घंटे में 150 अंकों के 150 प्रश्न।"}'::jsonb, '2026-08-04'::date, '[{"en":"Recruitment","hi":"भर्ती"},{"en":"Bihar","hi":"बिहार"}]'::jsonb, array['bihartet', 'bihar-stet']::text[]),
  ('ca-haryana-drive', '{"en":"Haryana announces 15,659 PRT, TGT and PGT posts","hi":"हरियाणा में 15,659 PRT, TGT एवं PGT पद घोषित"}'::jsonb, '{"en":"Recruitment runs through HSSC, HPSC and HKRN. The HSSC share is 8,394 TGT and PGT vacancies, with applications from 21 August to 21 September 2026 and a fee of Rs 500 for General and Rs 125 for reserved categories.","hi":"भर्ती HSSC, HPSC एवं HKRN के माध्यम से होगी। HSSC का हिस्सा 8,394 TGT एवं PGT रिक्तियाँ हैं, आवेदन 21 अगस्त से 21 सितंबर 2026 तक तथा शुल्क सामान्य ₹500 एवं आरक्षित वर्ग ₹125।"}'::jsonb, '2026-08-10'::date, '[{"en":"Recruitment","hi":"भर्ती"},{"en":"Haryana","hi":"हरियाणा"}]'::jsonb, array['htet', 'hssc-tgt-pgt']::text[])
